199:		const scope = globalThis as unknown as { onmessage: ((event: MessageEvent) => void) | null };
200:		const pending: MessageEvent[] = [];
201:		const buffer = (event: MessageEvent): void => {
202:			pending.push(event);
203:		};
204:		scope.onmessage = buffer;
205:		await import("@oh-my-pi/omp-stats/sync-worker");
206:		const handler = scope.onmessage;
207:		if (handler && handler !== buffer) {
208:			for (const event of pending) handler.call(scope, event);
209:		}
210:		return true;
211:	}
212:	// Bun flushes messages the parent posted before spawn once this entry's
213:	// top-level evaluation completes. Install a buffering inbox synchronously
214:	// before binding the selected worker's real handler so the parent's
215:	// synchronous `init` survives. The dynamically imported tab/eval modules
216:	// consume the same inbox after their module evaluation begins.
217:	if (arg === TAB_WORKER_ARG) {
218:		const parentPort = getWorkerParentPort();
219:		if (parentPort) installWorkerInbox(parentPort);
220:		await import("./tools/browser/tab-worker-entry");
221:		return true;
222:	}
223:	if (arg === COMPUTER_WORKER_ARG) {
224:		const parentPort = getWorkerParentPort();
225:		if (parentPort) installWorkerInbox(parentPort);
226:		const { startComputerWorker } = await import("./tools/computer/worker-entry");
227:		startComputerWorker();
228:		return true;
229:	}
230:	if (arg === JS_EVAL_WORKER_ARG) {
231:		const parentPort = getWorkerParentPort();
232:		if (parentPort) installWorkerInbox(parentPort);
233:		await import("./eval/js/worker-entry");
234:		return true;
235:	}
236:	if (arg === JS_EVAL_PROCESS_ARG) {
237:		// This selector is the synchronous bootstrap boundary: keep the evaluator
238:		// runtime and postmortem/inspector graph out of ordinary startup without
239:		// putting an await ahead of the subprocess message handler.
240:		const { startJsEvalProcess }: typeof JsProcessEntry = require("./eval/js/process-entry");
241:		// The .js subpath is the package's unconditional export for synchronous loading.
242:		const { interceptUnhandledRejections }: typeof Postmortem = require("@oh-my-pi/pi-utils/postmortem.js");
243:		// The JS evaluator forwards user-controlled payloads (tool-call args,
244:		// display outputs); a non-serializable one must fail that cell, not
245:		// SIGKILL the kernel and erase the eval session's state.
246:		await runIpcSubprocessWorker<JsWorkerInbound, JsWorkerOutbound>(
247:			transport => startJsEvalProcess(transport, interceptUnhandledRejections),
248:			{ rethrowConnectedSendErrors: true },
249:		);
250:		return true;
251:	}
252:	if (arg === STT_WORKER_ARG) {
253:		const { startSttWorker } = await import("./stt/asr-worker");
254:		await runIpcSubprocessWorker(startSttWorker);
255:		return true;
256:	}
257:	if (arg === TTS_WORKER_ARG) {
258:		const { startTtsWorker } = await import("./tts/tts-worker");
259:		await runIpcSubprocessWorker(startTtsWorker);
260:		return true;
261:	}
262:	if (arg === MNEMOPI_EMBED_WORKER_ARG) {
263:		const { startMnemopiEmbedWorker } = await import("./mnemopi/embed-worker");
264:		await runIpcSubprocessWorker(startMnemopiEmbedWorker);
265:		return true;
266:	}
267:	if (arg === STATS_ACTIVITY_WORKER_ARG) {
268:		const { startStatsActivityWorker } = await import("./stats/activity-worker");
269:		await runIpcSubprocessWorker(startStatsActivityWorker);
270:		return true;
271:	}
272:	if (arg === TERMINAL_OUTPUT_WORKER_ARG) {
273:		const parentPort = getWorkerParentPort();
274:		if (parentPort) installWorkerInbox(parentPort);
275:		// This selector is the isolation boundary; a static import would evaluate xterm in normal CLI startup.
276:		await import("./launch/terminal-output-worker");
277:		return true;
278:	}
279:	if (arg === DAEMON_BROKER_WORKER_ARG) {
280:		// Worker selectors must dispatch before the normal command graph loads.
281:		const { startDaemonBrokerFromEnvironment } = await import("./launch/broker");
282:		await startDaemonBrokerFromEnvironment();
283:		return true;
284:	}
285:	if (arg === LSP_MUX_WORKER_ARG) {
286:		const { startLspMuxFromEnvironment } = await import("./lsp/mux/server");
287:		await startLspMuxFromEnvironment();
288:		return true;
289:	}
290:	if (arg === BLOB_BROKER_WORKER_ARG) {
291:		const { startBlobBrokerFromEnvironment } = await import("./blob-broker/server");
292:		await startBlobBrokerFromEnvironment();
293:		return true;
294:	}
295:	return false;
296:}
