298:/**
299: * Boot a subprocess-isolated transformers.js worker over the parent's IPC
300: * channel and block until the parent disconnects. The tiny-model, STT, and TTS
301: * workers each run `onnxruntime-node` (loaded transitively by
302: * `@huggingface/transformers`) in a child address space because its NAPI
303: * finalizer segfaults Bun on shutdown (issue #1606); the parent `SIGKILL`s the
304: * child so that finalizer never runs in either process. This wires `process`
305: * IPC to the worker's typed transport, keeps the event loop alive while the
306: * worker is idle, and hard-kills the process on parent `disconnect`.
307: */
308:async function runIpcSubprocessWorker<In, Out>(
309:	start: (transport: {
310:		send(message: Out): void;
311:		sendAndFlush(message: Out): Promise<void>;
312:		onMessage(handler: (message: In) => void): () => void;
313:	}) => void,
314:	options?: {
315:		/**
316:		 * Rethrow send failures while the IPC channel is still connected instead
317:		 * of shutting down. A connected-channel failure means this particular
318:		 * message could not be serialized (e.g. a JS eval cell passed a function
319:		 * into tool args, a DataCloneError under advanced serialization) — the
320:		 * caller must see that error, exactly as Worker `postMessage` would
321:		 * deliver it, rather than losing the whole worker and its state.
322:		 * Channel-gone failures still shut down.
323:		 */
324:		rethrowConnectedSendErrors?: boolean;
325:	},
326:): Promise<void> {
327:	const { promise: shuttingDown, resolve: shutdown } = Promise.withResolvers<void>();
328:	type IpcSend = (this: NodeJS.Process, message: unknown, callback?: (error: Error | null) => void) => boolean;
329:	// `process.send` only exists when spawned with an IPC channel; the parent
330:	// always spawns us that way. If it's missing, the parent vanished and
331:	// there's no one to talk to.
332:	const ipcSend = (): IpcSend | undefined => (process as NodeJS.Process & { send?: IpcSend }).send;
333:	if (!ipcSend()) {
334:		// Intentional fall-through: shutdown() only resolves the promise;
335:		// the await + SIGKILL tail below is what actually exits.
336:		shutdown();
337:	}
338:	const send = (message: Out): void => {
339:		const sender = ipcSend();
340:		if (!sender) {
341:			shutdown();
342:			return;
343:		}
344:		try {
345:			sender.call(process, message);
346:		} catch (error) {
347:			if (options?.rethrowConnectedSendErrors && process.connected) throw error;
348:			shutdown();
349:		}
350:	};
351:	const sendAndFlush = (message: Out): Promise<void> => {
352:		const sender = ipcSend();
353:		if (!sender) {
354:			shutdown();
355:			return Promise.resolve();
356:		}
357:		const { promise, resolve } = Promise.withResolvers<void>();
358:		try {
359:			sender.call(process, message, () => resolve());
360:		} catch {
361:			shutdown();
362:			resolve();
363:		}
364:		return promise;
365:	};
366:	start({
367:		send,
368:		sendAndFlush,
369:		onMessage(handler) {
370:			const wrap = (data: unknown): void => handler(data as In);
371:			process.on("message", wrap);
372:			return () => {
373:				process.off("message", wrap);
374:			};
375:		},
376:	});
377:	let parentWatchdog: NodeJS.Timeout | undefined;
378:	const initialParentPid = process.ppid;
379:	if (process.platform === "win32" && initialParentPid <= 0) {
380:		shutdown();
381:	} else if (initialParentPid > 0) {
382:		let parentProcess: Process | null = null;
383:		let runningStatus: ProcessStatus | undefined;
384:		try {
385:			if (!process.env.PI_TEST_NO_NATIVES) {
386:				const natives = await import("@oh-my-pi/pi-natives");
387:				parentProcess = natives.Process.fromPid(initialParentPid);
388:				runningStatus = natives.ProcessStatus.Running;
389:			}
390:		} catch {}
391:
392:		// Note on container environments (Docker/Kubernetes): omp often runs as
393:		// PID 1, so workers start with process.ppid === 1. Treating ppid <= 1 as
394:		// an orphan at boot would break containerized workers. Instead, we allow
395:		// PID 1 to boot normally and detect post-spawn reparenting dynamically via
396:		// `process.ppid !== initialParentPid`.
397:		//
398:		// Note on Linux seccomp/kernels: On hosts where pidfd_open is blocked or
399:		// unavailable (e.g. pre-5.3 kernels, restrictive seccomp), Process.fromPid
400:		// returns null even when the parent is alive. We treat null as the native
401:		// handle being unavailable and fall through to the isParentAlive() check
402:		// rather than assuming null means dead at boot.
403:		const isParentAlive = (): boolean => {
404:			if (process.ppid !== initialParentPid) {
405:				return false;
406:			}
407:			if (parentProcess && runningStatus !== undefined) {
408:				try {
409:					return parentProcess.status() === runningStatus;
410:				} catch {}
411:			}
412:			try {
413:				process.kill(initialParentPid, 0);
414:				return true;
415:			} catch (err: unknown) {
416:				return (err as NodeJS.ErrnoException)?.code === "EPERM";
417:			}
418:		};
419:
420:		if (!isParentAlive()) {
421:			shutdown();
422:		} else {
423:			if (parentProcess) {
424:				void parentProcess.waitForExit().then(
425:					() => shutdown(),
426:					() => shutdown(),
427:				);
428:			}
429:			parentWatchdog = setInterval(() => {
430:				if (!isParentAlive()) {
431:					shutdown();
432:				}
433:			}, 1000);
434:			parentWatchdog.unref();
435:		}
436:	}
437:	const keepalive = setInterval(() => {}, 2 ** 30);
438:	// Parent went away (crashed, SIGKILL, etc.) — commit suicide so we don't
439:	// linger as an orphan. SIGKILL via `process.kill` keeps us symmetrical with
440:	// the parent's hard-kill on shutdown: skip every JS/native finalizer.
441:	process.on("disconnect", () => shutdown());
442:	try {
443:		await shuttingDown;
444:	} finally {
445:		clearInterval(keepalive);
446:		if (parentWatchdog) clearInterval(parentWatchdog);
447:	}
448:	process.kill(process.pid, "SIGKILL");
449:}
