451:/**
452: * Hidden subcommand that boots the ONNX tiny-model worker for one model: a
453: * detached process owning that model's socket (`OMP_TINY_WORKER_SOCKET`),
454: * shared by every omp process on the machine and exiting on its own when
455: * idle. It exists so `onnxruntime-node` (loaded transitively by
456: * `@huggingface/transformers`) never runs in an omp address space — its NAPI
457: * finalizer segfaults Bun on Windows (issue #1606).
458: */
459:async function runTinyWorker(): Promise<void> {
460:	const { startTinyWorkerFromEnvironment } = await import("./tiny/worker");
461:	await startTinyWorkerFromEnvironment();
462:}
