464:/** Run the CLI with the given argv (no `process.argv` prefix). */
465:export async function runCli(argv: string[]): Promise<void> {
466:	let resolvedArgv = argv;
467:	try {
468:		const extracted = extractProfileFlags(resolvedArgv);
469:		resolvedArgv = extracted.argv;
470:		if (extracted.profile !== undefined) {
471:			setProfile(extracted.profile);
472:		} else {
473:			// No explicit --profile: activate any OMP_PROFILE/PI_PROFILE inherited
474:			// from the environment. Module-load resolution deliberately swallows an
475:			// invalid value to avoid an uncaught throw before this try/catch is in
476:			// scope (see `readProfileFromEnvSafe` in dirs.ts), and callers may set
477:			// OMP_PROFILE after importing this module (profile aliases/tests). Surfacing
478:			// validation here turns `OMP_PROFILE=.. omp --version` into a clean error;
479:			// calling setProfile keeps every later path helper on the env-selected
480:			// profile instead of the default agent directory.
481:			setProfile(resolveProfileEnv(process.env.OMP_PROFILE, process.env.PI_PROFILE));
482:		}
483:		if (extracted.aliasName !== undefined) {
484:			// Command boundary: shell/path setup is used only by --alias.
485:			const { installProfileAlias, resolveProfileAliasCommandFromProcess } = await import("./cli/profile-alias");
486:			const profile = extracted.profile ?? getActiveProfile();
487:			if (!profile) {
488:				throw new Error("--alias requires --profile <name> or OMP_PROFILE");
489:			}
490:			const result = await installProfileAlias({
491:				profile,
492:				aliasName: extracted.aliasName,
493:				command: resolveProfileAliasCommandFromProcess(),
494:			});
495:			process.stdout.write(
496:				`Created ${result.aliasName} for profile ${result.profile} in ${result.configPath}\n` +
497:					`Restart your shell or run: ${result.reloadedWith}\n` +
498:					`Then use: ${result.aliasName} update, ${result.aliasName} --version, or ${result.aliasName}\n`,
499:			);
500:			return;
501:		}
502:	} catch (error) {
503:		const message = error instanceof Error ? error.message : String(error);
504:		process.stderr.write(`Error: ${message}\n`);
505:		process.exitCode = 1;
506:		return;
507:	}
508:
509:	// Declare this module as the worker-host entry now that the active profile
510:	// is resolved. The worker-host module is side-effect-free; importing
511:	// `@oh-my-pi/pi-utils/env` here would snapshot the wrong agent `.env`.
512:	// Gated on `isProcessEntry`: only the real CLI process entry is a valid
513:	// worker host. Worker-thread re-entry has `!Bun.isMainThread` (isProcessEntry === false),
514:	// and importers (`runCli` in profile-CLI tests, SDK embedding) have `import.meta.main === false`
515:	// — declaring there would poison `workerHostEntry()` for the whole test process, forcing eval/stats/
516:	// browser workers onto the same-realm inline fallback.
517:	// This must run before worker selector dispatch so that worker subprocesses
518:	// (e.g. stats activity) are registered as hosts and can themselves spawn worker threads.
519:	if (isProcessEntry) declareWorkerHostEntry();
520:
521:	// Worker-thread entry dispatch must run before the first `await`: the
522:	// stats sync worker's buffering onmessage handler is installed in the
523:	// synchronous prefix of `runWorkerEntrypoint`, and Bun flushes the
524:	// worker's parked initial messages as soon as the entry module's
525:	// top-level evaluation finishes.
526:	if (isWorkerHostSelector(resolvedArgv[0])) {
527:		// Invoke dispatch first so its inbox is installed before asynchronous
528:		// process-name setup yields; neither dependency belongs in prepaint.
529:		const [dispatched] = await Promise.all([runWorkerEntrypoint(resolvedArgv[0]), setFullProcessName()]);
530:		if (!dispatched) {
531:			process.stderr.write(`Error: unknown worker selector: ${resolvedArgv[0]}\n`);
532:			process.exitCode = 1;
533:		}
534:		return;
535:	}
536:
537:	if (resolvedArgv[0] === "--license") {
538:		// Command boundary: bundled notices are read only when requested.
539:		const { formatLicenseOutput } = await import("./cli/license");
540:		process.stdout.write(formatLicenseOutput());
541:		return;
542:	}
543:	let stopStartupComposer: (() => void) | undefined;
544:	if (
545:		!process.env.PI_TIMING &&
546:		process.stdin.isTTY === true &&
547:		process.stdout.isTTY === true &&
548:		resolvedArgv.every(arg => PREPAINT_SAFE_FLAGS[arg] === true)
549:	) {
550:		// Intentional exception to the static-import convention: this latency boundary
551:		// keeps the TUI graph out of worker, subcommand, help, and version launches.
552:		// Loading it statically would erase the measured cold-start improvement.
553:		const { beginStartupComposer, stopPendingStartupComposer } = await import("./modes/startup-composer");
554:		beginStartupComposer({ version: VERSION });
555:		stopStartupComposer = stopPendingStartupComposer;
556:	}
557:
558:	// The speculative composer owns stdin before either loader yields, so input
559:	// typed during initialization stays buffered. Neither graph is needed to
560:	// produce that frame.
561:	const helpOrVersion =
562:		resolvedArgv[0] === "--help" ||
563:		resolvedArgv[0] === "-h" ||
564:		resolvedArgv[0] === "--version" ||
565:		resolvedArgv[0] === "-v" ||
566:		resolvedArgv[0] === "help";
567:	await Promise.all([setFullProcessName(), helpOrVersion ? Promise.resolve() : installNetworkBootstrap()]);
568:
569:	if (resolvedArgv[0] === "--smoke-test") {
570:		await runSmokeTest();
571:		return;
572:	}
573:
574:	try {
575:		const [{ run }, { commands, resolveCliArgv }] = await Promise.all([
576:			import("@oh-my-pi/pi-utils/cli"),
577:			import("./cli-commands"),
578:		]);
579:		// --help and --version are handled by run() directly; --license returned above.
580:		// Everything else that isn't a known subcommand routes to "launch".
581:		const resolved = resolveCliArgv(resolvedArgv);
582:		if ("error" in resolved) {
583:			process.stderr.write(`error: ${resolved.error}\n`);
584:			process.exitCode = 1;
585:			return;
586:		}
587:		await run({ bin: APP_NAME, version: VERSION, argv: resolved.argv, commands, metadataHelp: showHelp });
588:	} finally {
589:		stopStartupComposer?.();
590:	}
591:}
592:
593:// Floating call instead of top-level await: TLA forces `--bytecode` (CJS
594:// lowering) builds to fail, and the entrypoint needs nothing after this.
595:// The catch mirrors what an unhandled TLA rejection produced: error dump to
596:// stderr, exit code 1. Success paths resolve without touching the exit code.
597:// Guarded so importing `runCli` (profile CLI tests, SDK embedding) does not
598:// launch the agent as a side effect. Worker threads re-enter this module as
599:// their entry with `import.meta.main === false`, so the worker-host dispatch
600:// is admitted via `!Bun.isMainThread`.
601:if (isProcessEntry || !Bun.isMainThread) {
602:	// A one-shot CLI run (`omp --help | head`, `omp --version | true`, `omp <sub> | grep -m1`)
603:	// whose stdout consumer closes before the write drains gets an EPIPE that Bun surfaces as
604:	// an unhandled rejection. Treat a vanished stdout peer as an ordinary Unix disconnect
605:	// (graceful exit) rather than the fatal path. Interactive launches register their own
606:	// terminal lifetime; help/version/subcommand launches never start one. See #10930. The
607:	// registration lives for the process — a one-shot entry exits right after runCli settles.
608:	if (isProcessEntry) {
609:		const { registerStdioDisconnectHandling }: typeof Postmortem = require("@oh-my-pi/pi-utils/postmortem.js");
610:		registerStdioDisconnectHandling();
611:	}
612:	runCli(process.argv.slice(2)).catch(async error => {
613:		// Failure boundary: inspector/postmortem is irrelevant to successful startup.
614:		const { fatal } = await import("@oh-my-pi/pi-utils/postmortem");
615:		fatal(error);
616:	});
617:}

